using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class RealityCoreShell:MonoBehaviour
{
private Transform root,heart;private Color dark,energy,ground;
public void Build(bool zero){dark=zero?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;energy=zero?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;ground=zero?StylizedArtDirection.ZeroGround:StylizedArtDirection.LumenGround;root=new GameObject("DF_RealityCoreShell").transform;root.SetParent(transform,false);BuildFoundation(zero);BuildReactor(zero);}
private void BuildFoundation(bool zero){Part("CorePlatform",PrimitiveType.Cylinder,new Vector3(0,.10f,0),new Vector3(3.8f,.16f,3.8f),Color.Lerp(ground,dark,.35f),Vector3.zero);for(int i=0;i<8;i++){float a=i*Mathf.PI*.25f;Vector3 p=new Vector3(Mathf.Cos(a)*3.0f,.32f,Mathf.Sin(a)*3.0f);Transform butt=Part("CoreButtress",PrimitiveType.Cube,p,new Vector3(1.25f,.55f,.72f),dark,new Vector3(0,-a*Mathf.Rad2Deg+90,zero?(i%2==0?8:-8):0));Part("CoreConduit",PrimitiveType.Cube,p+Vector3.up*.32f,new Vector3(.65f,.08f,.10f),energy,new Vector3(0,-a*Mathf.Rad2Deg+90,0),true);}}
private void BuildReactor(bool zero){for(int i=0;i<6;i++){float a=(i*60+30)*Mathf.Deg2Rad;float lean=zero?(i%2==0?14:-10):0;Part("ReactorPylon",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*1.55f,1.65f,Mathf.Sin(a)*1.55f),new Vector3(.48f,3.15f,.62f),dark,new Vector3(lean,-a*Mathf.Rad2Deg,zero?lean*.45f:0));Part("PylonEnergy",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*1.38f,1.75f,Mathf.Sin(a)*1.38f),new Vector3(.13f,2.25f,.16f),energy,new Vector3(lean,-a*Mathf.Rad2Deg,zero?lean*.45f:0),true);}Part("LowerReactor",PrimitiveType.Cylinder,new Vector3(0,.72f,0),new Vector3(1.28f,.72f,1.28f),dark,Vector3.zero);heart=Part("RealityHeart",PrimitiveType.Sphere,new Vector3(0,2.05f,0),Vector3.one*1.15f,energy,Vector3.zero,true);Part("UpperCrystal",PrimitiveType.Cube,new Vector3(0,3.05f,0),new Vector3(.82f,1.75f,.82f),energy,new Vector3(zero?18:0,45,zero?12:0),true);for(int i=0;i<4;i++){float a=(i*90+45)*Mathf.Deg2Rad;Part("CrownShard",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.85f,3.45f,Mathf.Sin(a)*.85f),new Vector3(.26f,1.35f,.26f),energy,new Vector3(zero?i*9:0,-i*45,zero?(i%2==0?16:-16):0),true);}}
private Transform Part(string n,PrimitiveType type,Vector3 p,Vector3 s,Color c,Vector3 r,bool pulse=false){GameObject g=GameObject.CreatePrimitive(type);g.name="DF_"+n;g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=s;g.transform.localRotation=Quaternion.Euler(r);Collider col=g.GetComponent<Collider>();if(col!=null)col.enabled=false;Renderer renderer=g.GetComponent<Renderer>();if(renderer!=null){Material m=renderer.material;m.color=c;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);if(pulse){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*3.2f);}}if(pulse)g.AddComponent<ArenaLightPulse>();return g.transform;}
}
}